            while c < w and out[r][c] != 0:
                word.append(out[r][c])
                c += 1
            words.append(word)

    # Repeated edge words are just duplicate references.
    unique_words = []
    for word in words:
        if word not in unique_words:
            unique_words.append(word)

    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
